static void enable_cpu_clocks ( void ) { struct clk_rst_ctlr * clkrst = ( clk_rst_ctlr * ) NV_PA_CLK_RST_BASE ; struct clk_pll_info * pllinfo = & tegra_pll_info_table [ CLOCK_ID_XCPU ] ; u32 reg ; debug ( "%s entry\n" , __func__ ) ; { reg = readl ( & clkrst -> crc_pll_simple [ SIMPLE_PLLX ] . pll_base ) ; debug ( "%s: PLLX base = 0x%08X\n" , __func__ , reg ) ; } ( reg & ( 1 << pllinfo -> lock_det ) ) == 0 ; debug ( "%s: PLLX locked, delay for stable clocks\n" , __func__ ) ; udelay ( PLL_STABILIZATION_DELAY ) ; debug ( "%s: Setting CCLK_BURST and DIVIDER\n" , __func__ ) ; writel ( CCLK_BURST_POLICY , & clkrst -> crc_cclk_brst_pol ) ; writel ( SUPER_CCLK_DIVIDER , & clkrst -> crc_super_cclk_div ) ; debug ( "%s: Enabling clock to all CPUs\n" , __func__ ) ; reg = CLR_CPU3_CLK_STP | CLR_CPU2_CLK_STP | CLR_CPU1_CLK_STP | CLR_CPU0_CLK_STP ; writel ( reg , & clkrst -> crc_clk_cpu_cmplx_clr ) ; debug ( "%s: Enabling main CPU complex clocks\n" , __func__ ) ; clock_enable ( PERIPH_ID_CPU ) ; clock_enable ( PERIPH_ID_CPULP ) ; clock_enable ( PERIPH_ID_CPUG ) ; } 